1	package book
2	
3	import (
4		"strings"
5		"testing"
6	)
7	
8	// setupModifyAmountReject 准备题述场景（现金与合约持仓限额充足、行情连续、未开日内
9	// 亏损保护）：现金 1000，A、B 持仓限额各 100；A 报价 seq1(时刻10)@10，B 报价
10	// seq1(时刻20)@20；账户总持仓金额上限 200。
11	// A 买单总量 10、限价 12，已按价格 9 成交 4（剩余 6）；B 买单数量 2、限价 20 未成交。
12	// 此时已持仓金额 4×10=40，未成交买单占用 6×max(12,10)+2×20=112，合计 152；
13	// 现金余额 964，买单现金占用 112。
14	func setupModifyAmountReject(t *testing.T) (e *Engine, aID, bID int64) {
15		t.Helper()
16		e, _ = NewEngine(1000)
17		mustSetMax(t, e, "A", 100)
18		mustSetMax(t, e, "B", 100)
19		mustQuote(t, e, "A", Quote{Seq: 1, Moment: 10, Price: 10}, 1)
20		mustQuote(t, e, "B", Quote{Seq: 1, Moment: 20, Price: 20}, 1)
21		if _, err := e.SetPositionAmountLimit(200); err != nil {
22			t.Fatal(err)
23		}
24	
25		aID = mustBuy(t, e, "A", 10, 12)
26		if _, err := e.Fill(Trade{TradeID: 1, OrderID: aID, Symbol: "A", Side: Buy, Price: 9, Qty: 4}); err != nil {
27			t.Fatal(err)
28		}
29		bID = mustBuy(t, e, "B", 2, 20)
30	
31		if e.Cash() != 964 || e.ReservedCash() != 112 || e.Position("A") != 4 || e.Position("B") != 0 {
32			t.Fatalf("前置资金与持仓错误: cash=%d reserved=%d posA=%d posB=%d",
33				e.Cash(), e.ReservedCash(), e.Position("A"), e.Position("B"))
34		}
35		if st := e.PositionAmountStatus(); !st.Enabled || st.Limit != 200 ||
36			st.Holding != 40 || st.BuyReserved != 112 || st.Total != 152 {
37			t.Fatalf("前置金额状态错误: %+v", st)
38		}
39		if o, _ := e.Order(aID); o.Qty != 10 || o.Limit != 12 || o.Filled != 4 ||
40			o.Status != StatusPartial || o.Remaining() != 6 {
41			t.Fatalf("A 订单前置状态错误: %+v", o)
42		}
43		if o, _ := e.Order(bID); o.Qty != 2 || o.Limit != 20 || o.Status != StatusPending {
44			t.Fatalf("B 订单前置状态错误: %+v", o)
45		}
46		return e, aID, bID
47	}
48	
49	// findModifyAmountReject 返回唯一一条 A 订单的金额超限修改拒绝记录。
50	func findModifyAmountReject(t *testing.T, e *Engine, aID int64) Record {
51		t.Helper()
52		var found []Record
53		for _, r := range e.Records() {
54			if r.Kind == RecordRejected && r.OrderID == aID && r.AmtEnabled {
55				found = append(found, r)
56			}
57		}
58		if len(found) != 1 {
59			t.Fatalf("金额超限修改拒绝记录应恰好一条，实际 %d 条", len(found))
60		}
61		return found[0]
62	}
63	
64	// TestModifyPartialBuyAmountLimitRejectRegression 复现题述场景：把部分成交的 A 买单
65	// 改为总量 12、限价 20 后，剩余 8 的新占用 8×max(20,10)=160 替换原剩余 6 的占用 72，
66	// 申请后合计 152-72+160=240 超过上限 200，必须拒绝。已成交的 4 份只计入持仓金额，
67	// 不能再算进买单占用（否则申请前合计不会是 152）；也绝不能撤销 B 订单腾额度。
68	// 本次调用只追加一条拒绝记录，关联原订单并固化申请参数、判断时的上限、两类金额、
69	// 修改前合计与申请后合计，以及参与判断的 A、B 报价定位（按合约排列且不重复）；
70	// 原订单、其他订单、资金与持仓全部保持调用前的值。
71	func TestModifyPartialBuyAmountLimitRejectRegression(t *testing.T) {
72		e, aID, bID := setupModifyAmountReject(t)
73	
74		before := len(e.Records())
75		err := e.Modify(aID, 12, 20)
76		if err == nil {
77			t.Fatal("申请后合计 240 超过上限 200 必须拒绝修改")
78		}
79		expectErr(t, err, "超过账户总持仓金额上限")
80	
81		// 只追加一条拒绝记录；不得产生修改成功或撤销记录（尤其不能撤 B 单腾额度）。
82		recs := e.Records()
83		if len(recs) != before+1 {
84			t.Fatalf("只能追加一条拒绝记录，实际新增 %d 条", len(recs)-before)
85		}
86		rj := recs[len(recs)-1]
87		if rj.Kind != RecordRejected {
88			t.Fatalf("新增记录必须是拒绝记录: %+v", rj)
89		}
90		for _, r := range recs[before:] {
91			if r.Kind == RecordModified || r.Kind == RecordCanceled {
92				t.Fatalf("金额超限拒绝不得产生修改或撤销记录: %+v", r)
93			}
94		}
95	
96		// 记录关联原订单并保留申请的总量与限价。
97		if rj.OrderID != aID || rj.Symbol != "A" || rj.Side != Buy || rj.Qty != 12 || rj.Limit != 20 {
98			t.Fatalf("拒绝记录须关联原订单并保留申请参数: %+v", rj)
99		}
100		if !strings.Contains(rj.Reason, "超过账户总持仓金额上限") {
101			t.Fatalf("拒绝原因须说明金额超限: %q", rj.Reason)
102		}
103		// 固化判断时的上限、两类金额、修改前合计与申请后合计：
104		// 已持仓 40、买单占用 112（只含未成交剩余量，已成交 4 份不得重复计入）、
105		// 修改前合计 152、申请后合计 240。
106		if !rj.AmtEnabled || rj.AmtLimit != 200 ||
107			rj.AmtHolding != 40 || rj.AmtBuyReserved != 112 ||
108			rj.AmtTotal != 152 || rj.AmtApplyTotal != 240 {
109			t.Fatalf("拒绝记录金额快照错误: %+v", rj)
110		}
111		// 参与判断的 A、B 报价都留下合约、序号、时刻和价格，按合约排列且不重复。
112		wantRefs := []RiskQuoteRef{
113			{Symbol: "A", Seq: 1, Moment: 10, Price: 10},
114			{Symbol: "B", Seq: 1, Moment: 20, Price: 20},
115		}
116		if len(rj.AmtQuoteRefs) != len(wantRefs) {
117			t.Fatalf("报价定位应为 A、B 各一条: %+v", rj.AmtQuoteRefs)
118		}
119		for i, want := range wantRefs {
120			if rj.AmtQuoteRefs[i] != want {
121				t.Fatalf("报价定位[%d]错误: 期望 %+v，实际 %+v（须按合约排列且不重复）",
122					i, want, rj.AmtQuoteRefs[i])
123			}
124		}
125	
126		// 拒绝不改动原订单：A 仍为总量 10、限价 12、已成交 4、剩余 6。
127		if o, _ := e.Order(aID); o.Qty != 10 || o.Limit != 12 || o.Filled != 4 ||
128			o.Status != StatusPartial || o.Remaining() != 6 {
129			t.Fatalf("拒绝不得改变 A 订单: %+v", o)
130		}
131		// B 订单继续有效，绝不能被撤销腾额度。
132		if o, _ := e.Order(bID); o.Qty != 2 || o.Limit != 20 || o.Status != StatusPending || o.Remaining() != 2 {
133			t.Fatalf("拒绝不得影响 B 订单: %+v", o)
134		}
135		// 现金余额、买单现金占用与持仓均保持调用前的值。
136		if e.Cash() != 964 || e.ReservedCash() != 112 || e.AvailableCash() != 852 ||
137			e.Position("A") != 4 || e.Position("B") != 0 {
138			t.Fatalf("拒绝不得改变资金与持仓: cash=%d reserved=%d available=%d posA=%d posB=%d",
139				e.Cash(), e.ReservedCash(), e.AvailableCash(), e.Position("A"), e.Position("B"))
140		}
141		if st := e.PositionAmountStatus(); st.Holding != 40 || st.BuyReserved != 112 || st.Total != 152 {
142			t.Fatalf("拒绝后金额合计保持 152: %+v", st)
143		}
144	}
145	
146	// TestModifyAmountRejectRecordImmutability 验证拒绝记录保存的是拒绝发生时的事实：
147	// 随后更新报价、调高金额上限并成功修改同一订单后，旧记录仍保留 152、240、上限 200
148	// 和原报价定位；修改查询返回的记录或其中的报价信息，也不能影响再次查询得到的历史内容。
149	func TestModifyAmountRejectRecordImmutability(t *testing.T) {
150		e, aID, bID := setupModifyAmountReject(t)
151	
152		if err := e.Modify(aID, 12, 20); err == nil {
153			t.Fatal("前置：申请后合计 240 超限必须拒绝")
154		}
155	
156		// 篡改查询返回的副本（含报价定位切片），再次查询的历史内容不得受影响。
157		tampered := e.Records()
158		for i := range tampered {
159			if tampered[i].Kind == RecordRejected && tampered[i].OrderID == aID && tampered[i].AmtEnabled {
160				tampered[i].AmtLimit = 9999
161				tampered[i].AmtTotal = 1
162				tampered[i].AmtApplyTotal = 1
163				tampered[i].AmtQuoteRefs[0].Price = 9999
164				tampered[i].AmtQuoteRefs[1].Seq = 99
165			}
166		}
167		rj := findModifyAmountReject(t, e, aID)
168		if rj.AmtLimit != 200 || rj.AmtTotal != 152 || rj.AmtApplyTotal != 240 {
169			t.Fatalf("篡改查询副本不得改写历史记录: %+v", rj)
170		}
171		if rj.AmtQuoteRefs[0] != (RiskQuoteRef{Symbol: "A", Seq: 1, Moment: 10, Price: 10}) ||
172			rj.AmtQuoteRefs[1] != (RiskQuoteRef{Symbol: "B", Seq: 1, Moment: 20, Price: 20}) {
173			t.Fatalf("篡改查询副本不得改写历史报价定位: %+v", rj.AmtQuoteRefs)
174		}
175	
176		// 随后调高上限、更新报价并成功修改同一订单。
177		if _, err := e.SetPositionAmountLimit(1000); err != nil {
178			t.Fatal(err)
179		}
180		mustQuote(t, e, "A", Quote{Seq: 2, Moment: 11, Price: 30}, 1)
181		mustQuote(t, e, "B", Quote{Seq: 2, Moment: 21, Price: 30}, 1)
182		mustModify(t, e, aID, 12, 20)
183		if o, _ := e.Order(aID); o.Qty != 12 || o.Limit != 20 || o.Filled != 4 || o.Remaining() != 8 {
184			t.Fatalf("调高上限后同一订单应能成功修改: %+v", o)
185		}
186		if o, _ := e.Order(bID); o.Status != StatusPending {
187			t.Fatalf("B 订单应继续有效: %+v", o)
188		}
189	
190		// 旧拒绝记录仍保留拒绝发生时的事实：合计 152、申请后 240、上限 200、
191		// 原报价定位（A seq1@10、B seq1@20），不被后续报价与成功修改改写。
192		rj = findModifyAmountReject(t, e, aID)
193		if rj.AmtLimit != 200 || rj.AmtHolding != 40 || rj.AmtBuyReserved != 112 ||
194			rj.AmtTotal != 152 || rj.AmtApplyTotal != 240 {
195			t.Fatalf("后续操作不得改写旧拒绝记录的金额快照: %+v", rj)
196		}
197		if rj.Qty != 12 || rj.Limit != 20 || rj.OrderID != aID {
198			t.Fatalf("后续成功修改不得改写旧拒绝记录的申请参数: %+v", rj)
199		}
200		if rj.AmtQuoteRefs[0] != (RiskQuoteRef{Symbol: "A", Seq: 1, Moment: 10, Price: 10}) ||
201			rj.AmtQuoteRefs[1] != (RiskQuoteRef{Symbol: "B", Seq: 1, Moment: 20, Price: 20}) {
202			t.Fatalf("后续报价不得改写旧记录的报价定位: %+v", rj.AmtQuoteRefs)
203		}
204	}
205	
206	// TestModifyAmountExactlyAtLimitAllowed 金额刚好等于上限的修改仍按已有规则允许：
207	// A 改为总量 12、限价 15 后，新占用 8×max(15,10)=120，申请后合计 152-72+120=200
208	// 恰好等于上限，必须成功且不应产生金额超限拒绝记录。
209	func TestModifyAmountExactlyAtLimitAllowed(t *testing.T) {
210		e, aID, bID := setupModifyAmountReject(t)
211	
212		before := len(e.Records())
213		mustModify(t, e, aID, 12, 15)
214	
215		recs := e.Records()
216		if len(recs) != before+1 || recs[len(recs)-1].Kind != RecordModified {
217			t.Fatalf("恰好等于上限的修改必须成功且只留一条修改记录，新增 %d 条", len(recs)-before)
218		}
219		for _, r := range recs[before:] {
220			if r.Kind == RecordRejected {
221				t.Fatalf("恰好等于上限不得产生金额超限拒绝记录: %+v", r)
222			}
223		}
224		if o, _ := e.Order(aID); o.Qty != 12 || o.Limit != 15 || o.Filled != 4 ||
225			o.Status != StatusPartial || o.Remaining() != 8 {
226			t.Fatalf("恰好等于上限的修改应生效: %+v", o)
227		}
228		if st := e.PositionAmountStatus(); st.Holding != 40 || st.BuyReserved != 160 || st.Total != 200 {
229			t.Fatalf("修改后合计应恰好等于上限 200: %+v", st)
230		}
231		if o, _ := e.Order(bID); o.Status != StatusPending || o.Qty != 2 {
232			t.Fatalf("B 订单不得受影响: %+v", o)
233		}
234	}
