type OrderStatus int

const (
	// StatusPending 待成交：订单已接受，尚无成交。
	StatusPending OrderStatus = iota + 1
	// StatusPartial 部分成交。
	StatusPartial
	// StatusFilled 全部成交。
	StatusFilled
	// StatusCanceled 已撤销（可能已有部分成交）。
	StatusCanceled
)

// String 返回状态的中文描述。
func (s OrderStatus) String() string {
	switch s {
	case StatusPending:
		return "待成交"
	case StatusPartial:
		return "部分成交"
	case StatusFilled:
		return "全部成交"
	case StatusCanceled:
		return "已撤销"
	default:
		return "未知状态"
	}
}

// Quote 是某个合约的一条报价。序号从 1 开始且必须连续推进，
// Moment 为模拟时刻，Price 为正整数价格（最小单位）。
type Quote struct {
	Seq    int64
	Moment int64
	Price  int64
}

// Order 是一笔已被接受的委托。
type Order struct {
	ID     int64
	Symbol string
	Side   Side
	Limit  int64 // 限价（正整数）
	Qty    int64 // 原始委托数量
	Filled int64 // 已成交数量
	Status OrderStatus
	Reason string // 撤销原因（StatusCanceled 时）
}

// Remaining 返回订单尚未成交且仍有效的数量；已撤销订单的剩余量已取消，返回 0。
func (o Order) Remaining() int64 {
	if o.Status == StatusCanceled {
		return 0
	}
	return o.Qty - o.Filled
}

// activeBuy 是“有效买单”的唯一判断，日内亏损保护撤单、账户总持仓金额计算与
// 撤单、合约持仓限额下调撤单及行情补齐预检都经此判断哪些订单还有有效未成交部分：
//
//   - 待成交与部分成交的买单，只要仍有未成交部分（Remaining > 0）即为有效，
//     继续参与相应的占用计算与撤单选择；
//   - 全部成交或已撤销的订单不再参与（Remaining 已为 0）；卖单从不进入买单集合；
//   - 修改过总量或限价的买单按当前参数与已成交量确定剩余量，是否有效随之变化，
//     但其在合约接受序列（buyOrderIDs）中的位置不变，仍沿用最初接受的顺序。
//
// 各功能在此判断之上只叠加各自的集合范围（单合约接受序列或全账户订单）、
// 撤销次序与停止条件。o 为 nil（订单不存在）时不是有效买单。
func activeBuy(o *Order) bool {
	return o != nil && o.Side == Buy &&
		o.Status != StatusFilled && o.Status != StatusCanceled && o.Remaining() > 0
}

// Trade 是调用方提交的一笔成交。TradeID 由调用方给出且必须唯一，
// 同一编号重复提交时按幂等规则处理（见 Engine.Fill）。
type Trade struct {
	TradeID int64
	OrderID int64
	Symbol  string
	Side    Side
	Price   int64 // 成交价（正整数）
	Qty     int64 // 本次成交量（正整数）
}

// FillResult 是一笔成交被接受后返回的结果。
type FillResult struct {
	TradeID   int64
