package main

import (
	"fmt"

	"github.com/descikazuyq/book-risk/book"
)

func must(err error) {
	if err != nil {
		panic(err)
	}
}

func main() {
	e, err := book.NewEngine(2000) // 创建账户：初始现金 2000
	must(err)
	_, err = e.SetMaxPosition("A", 100) // A、B 最大持仓量各 100
	must(err)
	_, err = e.SetMaxPosition("B", 100)
	must(err)

	// A、B 的首条报价：A 序号 1、时刻 10、价格 15；B 序号 1、时刻 20、价格 20。
	// 不开启日内亏损保护，行情没有缺口。
	_, err = e.UpdateQuote("A", book.Quote{Seq: 1, Moment: 10, Price: 15})
	must(err)
	_, err = e.UpdateQuote("B", book.Quote{Seq: 1, Moment: 20, Price: 20})
	must(err)

	// 账户总持仓金额上限 260。
	_, err = e.SetPositionAmountLimit(260)
	must(err)

	// 接受 A 的总量 10、限价 12 买单，按成交价 11 买入其中 4 份（剩余 6 份）。
	aID, err := e.Buy("A", 10, 12)
	must(err)
	_, err = e.Fill(book.Trade{TradeID: 1, OrderID: aID, Symbol: "A", Side: book.Buy, Price: 11, Qty: 4})
	must(err)
	// 再接受 B 的数量 3、限价 18 买单（尚未成交）。
	bID, err := e.Buy("B", 3, 18)
	must(err)
	fmt.Println("订单编号:", aID, bID)

	show := func(prefix string) {
		st := e.PositionAmountStatus()
		fmt.Println(prefix+": 现金", e.Cash(), "占用现金", e.ReservedCash(), "可用现金", e.AvailableCash())
		fmt.Println(prefix+": 持仓 A", e.Position("A"), "B", e.Position("B"))
		fmt.Println(prefix+": 上限", st.Limit, "持仓市值", st.Holding, "买单金额占用", st.BuyReserved, "合计", st.Total)
		for _, id := range []int64{aID, bID} {
			o, _ := e.Order(id)
			fmt.Printf("%s: 订单 %d %s 总量 %d 限价 %d 已成交 %d 有效剩余量 %d\n",
				prefix, id, o.Status, o.Qty, o.Limit, o.Filled, o.Remaining())
		}
	}

	show("两单接受后")

	// ---- 第一次申请：A 改为总量 12、限价 20，申请后合计 280 > 260，应被拒绝 ----
	recsBefore := len(e.Records())
	err = e.Modify(aID, 12, 20)
	fmt.Println("改为 12@20:", err)

	show("拒绝修改后")

	for _, r := range e.Records()[recsBefore:] {
		fmt.Printf("记录: %s 订单=%d 申请总量=%d 申请限价=%d 上限=%d 持仓市值=%d 买单金额占用=%d 修改前合计=%d 申请后合计=%d\n",
			r.Kind, r.OrderID, r.Qty, r.Limit, r.AmtLimit, r.AmtHolding, r.AmtBuyReserved, r.AmtTotal, r.AmtApplyTotal)
		for _, ref := range r.AmtQuoteRefs {
			fmt.Printf("  参与报价: 合约 %s 序号 %d 时刻 %d 价格 %d\n", ref.Symbol, ref.Seq, ref.Moment, ref.Price)
		}
		fmt.Println("  原因:", r.Reason)
	}

	// ---- 第二次申请：同一订单改为总量 11、限价 20，申请后合计恰好 260，允许成功 ----
	recsBefore = len(e.Records())
	must(e.Modify(aID, 11, 20))
	fmt.Println("改为 11@20: <nil>")

	show("成功修改后")

	for _, r := range e.Records()[recsBefore:] {
		fmt.Printf("记录: %s 订单=%d 新总量=%d 新限价=%d 已成交=%d 剩余=%d 旧总量=%d 旧限价=%d 旧已成交=%d\n",
			r.Kind, r.OrderID, r.Qty, r.Limit, r.Filled, r.Remaining, r.OldQty, r.OldLimit, r.OldFilled)
	}

	// 成功修改之后，此前的拒绝记录仍保留失败时点的事实，不被改写。
	var rj book.Record
	for _, r := range e.Records() {
		if r.Kind == book.RecordRejected && r.OrderID == aID && r.AmtEnabled {
			rj = r
		}
	}
	fmt.Printf("旧拒绝记录仍为: 申请 %d@%d 上限=%d 修改前合计=%d 申请后合计=%d\n",
		rj.Qty, rj.Limit, rj.AmtLimit, rj.AmtTotal, rj.AmtApplyTotal)
	for _, ref := range rj.AmtQuoteRefs {
		fmt.Printf("  旧记录参与报价: 合约 %s 序号 %d 时刻 %d 价格 %d\n", ref.Symbol, ref.Seq, ref.Moment, ref.Price)
	}
}

